<script>
"use strict";

// ---------------------------------------------------------------------------
// 1. FROZEN MODEL (identical to app.R)
// ---------------------------------------------------------------------------
const BETA = {                      // log2-scale coefficients
  HELLS:   -0.482344508382028,
  PUF60:    0.127510405914826,
  ASPHD1:   0.282563294313835,
  KRT16:    0.0957663490253585,
  EXOSC4:   0.30845567542535,
  RARRES1: -0.274428274970933
};
const TRAIN_MEAN = {                // TCGA training means of log2(TPM + 1)
  HELLS:   3.09802542260527,
  PUF60:   7.32902189745047,
  ASPHD1:  2.75319363036956,
  KRT16:   6.96911433308933,
  EXOSC4:  5.89908187291191,
  RARRES1: 7.09854812211672
};
const RISK_CUTOFF = -0.10811199230221;   // median risk score in TCGA-TNBC (n = 187)
const GENES = Object.keys(BETA);

// Example data: 10 made-up patients (not real patient data)
const EXAMPLE_CSV =
  "Patient_ID,ASPHD1,EXOSC4,HELLS,KRT16,PUF60,RARRES1\n" +
  "Example_01,4.035,6.642,1.479,6.589,7.801,7.984\n" +
  "Example_02,1.233,5.200,3.313,3.787,7.156,3.582\n" +
  "Example_03,2.766,4.671,3.169,10.526,8.504,9.546\n" +
  "Example_04,0.170,6.427,2.609,3.393,7.485,8.627\n" +
  "Example_05,6.133,5.631,4.208,0.000,6.999,7.028\n" +
  "Example_06,1.737,6.894,2.861,9.725,8.255,4.833\n" +
  "Example_07,2.460,5.802,2.909,4.588,6.589,8.080\n" +
  "Example_08,1.261,5.342,3.822,9.019,7.330,4.292\n" +
  "Example_09,0.000,6.015,3.052,9.660,8.178,6.040\n" +
  "Example_10,2.420,5.875,3.167,8.309,8.566,8.077\n";

// ---------------------------------------------------------------------------
// 2. HELPERS
// ---------------------------------------------------------------------------
const $ = id => document.getElementById(id);
let results = null;

function round(x, d) { const f = Math.pow(10, d); return Math.round(x * f) / f; }

function showMsg(text, kind) {
  const m = $("msg");
  m.className = "msg " + (kind || "");
  m.innerHTML = text;
}

// CSV parser: handles quoted fields, commas/newlines inside quotes, CRLF and a UTF-8 BOM
function parseCSV(text) {
  text = text.replace(/^﻿/, "");
  const rows = []; let row = []; let field = ""; let q = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) {
      if (c === '"') { if (text[i + 1] === '"') { field += '"'; i++; } else q = false; }
      else field += c;
    } else if (c === '"') q = true;
    else if (c === ",") { row.push(field); field = ""; }
    else if (c === "\n" || c === "\r") {
      if (c === "\r" && text[i + 1] === "\n") i++;
      row.push(field); rows.push(row); row = []; field = "";
    } else field += c;
  }
  if (field !== "" || row.length) { row.push(field); rows.push(row); }
  return rows.filter(r => !(r.length === 1 && r[0].trim() === ""));
}

function escapeHTML(s) {
  return String(s).replace(/[&<>"']/g, c => ({ "&":"&amp;", "<":"&lt;", ">":"&gt;", '"':"&quot;", "'":"&#39;" }[c]));
}

function download(name, blob) {
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob); a.download = name;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(a.href), 1000);
}

function today() { return new Date().toISOString().slice(0, 10); }

// ---------------------------------------------------------------------------
// 3. CALCULATION
// ---------------------------------------------------------------------------
function calculate(text) {
  const rows = parseCSV(text);
  if (rows.length < 2) return { error: "Error: the file has no data rows." };
  const header = rows[0].map(h => h.trim());
  const idCol = header.indexOf("Patient_ID");
  if (idCol < 0) return { error: "Error: 'Patient_ID' column is missing." };
  const missing = GENES.filter(g => header.indexOf(g) < 0);
  if (missing.length) return { error: "Error: missing genes: " + missing.join(", ") };
  const geneCol = {}; GENES.forEach(g => geneCol[g] = header.indexOf(g));

  const out = []; let maxVal = -Infinity;
  for (let r = 1; r < rows.length; r++) {
    let score = 0;
    for (const g of GENES) {
      const raw = (rows[r][geneCol[g]] ?? "").trim();
      const x = raw === "" || raw.toUpperCase() === "NA" ? NaN : Number(raw);
      if (!Number.isFinite(x)) {
        return { error: "Error: non-numeric or missing expression values in the 6 genes (row " + (r + 1) + ", " + escapeHTML(g) + ")." };
      }
      if (x > maxVal) maxVal = x;
      score += BETA[g] * (x - TRAIN_MEAN[g]);
    }
    out.push({
      Patient_ID: (rows[r][idCol] ?? "").trim(),
      Risk_Score: score,
      // compare at 8 decimals so floating-point noise cannot move the median
      // patient: a score equal to the TCGA median is Low-Risk, as in training
      Risk_Group: round(score, 8) > round(RISK_CUTOFF, 8) ? "High-Risk" : "Low-Risk"
    });
  }
  return { data: out, warn: maxVal > 30 ? "Warning: values look unlogged. Expected log2(TPM + 1)." : null };
}

// ---------------------------------------------------------------------------
// 4. OUTPUT: table, summary, plot
// ---------------------------------------------------------------------------
function renderTable(data) {
  let h = "<tr><th>Patient_ID</th><th>Risk_Score</th><th>Risk_Group</th></tr>";
  for (const d of data) {
    h += "<tr><td>" + escapeHTML(d.Patient_ID) + "</td><td>" + d.Risk_Score.toFixed(4) +
         "</td><td><span class='pill " + d.Risk_Group + "'>" + d.Risk_Group + "</span></td></tr>";
  }
  $("tbl").innerHTML = h;
  const nH = data.filter(d => d.Risk_Group === "High-Risk").length;
  $("summary").textContent = data.length + " patients: " + nH + " High-Risk, " + (data.length - nH) + " Low-Risk.";
}

function drawPlot(data) {
  const cv = $("plot"), ctx = cv.getContext("2d");
  const W = cv.width, H = cv.height;
  const m = { l: 140, r: 260, t: 90, b: 90 };
  const pw = W - m.l - m.r, ph = H - m.t - m.b;
  const d = data.slice().sort((a, b) => a.Risk_Score - b.Risk_Score);
  const vals = d.map(x => x.Risk_Score).concat([RISK_CUTOFF, 0]);
  let lo = Math.min(...vals), hi = Math.max(...vals);
  const pad = (hi - lo) * 0.08 || 0.5; lo -= pad; hi += pad;
  const y = v => m.t + ph - (v - lo) / (hi - lo) * ph;

  ctx.fillStyle = "#fff"; ctx.fillRect(0, 0, W, H);
  ctx.font = "28px Arial"; ctx.fillStyle = "#222"; ctx.textBaseline = "middle";

  // grid + y axis ticks
  const step = niceStep((hi - lo) / 6);
  ctx.strokeStyle = "#e6e6e6"; ctx.lineWidth = 2; ctx.textAlign = "right";
  for (let t = Math.ceil(lo / step) * step; t <= hi; t += step) {
    ctx.beginPath(); ctx.moveTo(m.l, y(t)); ctx.lineTo(m.l + pw, y(t)); ctx.stroke();
    ctx.fillText(+t.toFixed(3), m.l - 14, y(t));
  }

  // bars
  const bw = pw / d.length;
  d.forEach((x, i) => {
    ctx.fillStyle = x.Risk_Group === "High-Risk" ? "#d9534f" : "#5cb85c";
    const y0 = y(0), y1 = y(x.Risk_Score);
    ctx.fillRect(m.l + i * bw + bw * 0.15, Math.min(y0, y1), Math.max(bw * 0.7, 1), Math.abs(y1 - y0));
  });

  // cutoff line
  ctx.strokeStyle = "#000"; ctx.lineWidth = 3; ctx.setLineDash([14, 10]);
  ctx.beginPath(); ctx.moveTo(m.l, y(RISK_CUTOFF)); ctx.lineTo(m.l + pw, y(RISK_CUTOFF)); ctx.stroke();
  ctx.setLineDash([]);

  // titles and labels
  ctx.textAlign = "left"; ctx.font = "bold 34px Arial"; ctx.fillStyle = "#222";
  ctx.fillText("Patient Risk Score Distribution", m.l, 42);
  ctx.font = "28px Arial"; ctx.textAlign = "center";
  ctx.fillText("Patients (ordered by score)", m.l + pw / 2, H - 40);
  ctx.save(); ctx.translate(44, m.t + ph / 2); ctx.rotate(-Math.PI / 2);
  ctx.fillText("Risk score", 0, 0); ctx.restore();

  // legend
  ctx.textAlign = "left"; const lx = m.l + pw + 40;
  ctx.fillText("Risk group", lx, m.t + 10);
  [["High-Risk", "#d9534f"], ["Low-Risk", "#5cb85c"]].forEach(([lab, col], k) => {
    ctx.fillStyle = col; ctx.fillRect(lx, m.t + 50 + k * 50, 32, 32);
    ctx.fillStyle = "#222"; ctx.fillText(lab, lx + 46, m.t + 66 + k * 50);
  });
  ctx.strokeStyle = "#000"; ctx.lineWidth = 3; ctx.setLineDash([14, 10]);
  ctx.beginPath(); ctx.moveTo(lx, m.t + 176); ctx.lineTo(lx + 32, m.t + 176); ctx.stroke(); ctx.setLineDash([]);
  ctx.fillText("TCGA cutoff", lx + 46, m.t + 176);
}

function niceStep(raw) {
  const p = Math.pow(10, Math.floor(Math.log10(raw))), f = raw / p;
  return (f < 1.5 ? 1 : f < 3 ? 2 : f < 7 ? 5 : 10) * p;
}

// Run the calculation on CSV text and show the results
function run(text, okNote) {
  const res = calculate(text);
  if (res.error) {
    results = null; showMsg(res.error, "error");
    $("out").classList.add("hidden"); $("placeholder").classList.remove("hidden");
    $("dlTable").disabled = $("dlPlot").disabled = true; return;
  }
  results = res.data;
  if (res.warn) showMsg(res.warn, "warn");
  else if (okNote) showMsg(okNote, "ok");
  else showMsg("", "");
  renderTable(results); drawPlot(results);
  $("out").classList.remove("hidden"); $("placeholder").classList.add("hidden");
  $("dlTable").disabled = $("dlPlot").disabled = false;
}

// ---------------------------------------------------------------------------
// 5. EVENTS
// ---------------------------------------------------------------------------
$("file").addEventListener("change", () => { $("calc").disabled = !$("file").files.length; });

$("calc").addEventListener("click", () => {
  const f = $("file").files[0]; if (!f) return;
  const reader = new FileReader();
  reader.onload = e => run(e.target.result, null);
  reader.readAsText(f);
});

$("loadExample").addEventListener("click", () => {
  run(EXAMPLE_CSV, "Example data loaded: 10 made-up patients (not real patient data). The expected result is listed in Help.");
});

$("dlTable").addEventListener("click", () => {
  if (!results) return;
  const q = s => '"' + String(s).replace(/"/g, '""') + '"';
  let csv = '"Patient_ID","Risk_Score","Risk_Group"\n';
  for (const d of results) csv += q(d.Patient_ID) + "," + round(d.Risk_Score, 4) + "," + q(d.Risk_Group) + "\n";
  download("Risk_Scores_" + today() + ".csv", new Blob([csv], { type: "text/csv" }));
});

$("dlPlot").addEventListener("click", () => {
  $("plot").toBlob(b => download("Risk_Distribution_" + today() + ".png", b), "image/png");
});

$("dlTemplate").addEventListener("click", () => {
  const csv = "Patient_ID," + GENES.join(",") + "\n";
  download("TNBC_risk_input_template.csv", new Blob([csv], { type: "text/csv" }));
});

$("dlExample").addEventListener("click", () => {
  download("TNBC_risk_example_data.csv", new Blob([EXAMPLE_CSV], { type: "text/csv" }));
});
</script>
</body>
</html>
